#include <string>
#include <vector>

class Solution {
public:
    int equalCountSubstrings(std::string s, int count) {
        int n = s.size();
        int ans = 0;

        for (int u = 1; u <= 26; ++u) {
            int length = u * count;
            if (length > n) break;

            std::vector<int> freq(26, 0);
            int validChars = 0;

            for (int i = 0; i < n; ++i) {
                int cIn = s[i] - 'a';
                freq[cIn]++;
                if (freq[cIn] == count) validChars++;
                else if (freq[cIn] == count + 1) validChars--;

                if (i >= length) {
                    int cOut = s[i - length] - 'a';
                    if (freq[cOut] == count) validChars--;
                    else if (freq[cOut] == count + 1) validChars++;
                    freq[cOut]--;
                }

                if (i >= length - 1 && validChars == u) {
                    ans++;
                }
            }
        }
        return ans;
    }
};

class Solution {
    public int equalCountSubstrings(String s, int count) {
        int n = s.length();
        int ans = 0;

        for (int u = 1; u <= 26; u++) {
            int length = u * count;
            if (length > n) break;

            int[] freq = new int[26];
            int validChars = 0;

            for (int i = 0; i < n; i++) {
                int cIn = s.charAt(i) - 'a';
                freq[cIn]++;
                if (freq[cIn] == count) validChars++;
                else if (freq[cIn] == count + 1) validChars--;

                if (i >= length) {
                    int cOut = s.charAt(i - length) - 'a';
                    if (freq[cOut] == count) validChars--;
                    else if (freq[cOut] == count + 1) validChars++;
                    freq[cOut]--;
                }

                if (i >= length - 1 && validChars == u) {
                    ans++;
                }
            }
        }
        return ans;
    }
}

