var equalCountSubstrings = function(s, count) {
    const n = s.length;
    let ans = 0;

    for (let u = 1; u <= 26; u++) {
        const length = u * count;
        if (length > n) break;

        const freq = new Int32Array(26);
        let validChars = 0;

        for (let i = 0; i < n; i++) {
            const cIn = s.charCodeAt(i) - 97;
            freq[cIn]++;
            if (freq[cIn] === count) validChars++;
            else if (freq[cIn] === count + 1) validChars--;

            if (i >= length) {
                const cOut = s.charCodeAt(i - length) - 97;
                if (freq[cOut] === count) validChars--;
                else if (freq[cOut] === count + 1) validChars++;
                freq[cOut]--;
            }

            if (i >= length - 1 && validChars === u) {
                ans++;
            }
        }
    }
    return ans;
};
